# Per-top simulator boundary files for the HDL verification wrappers and the UVM
# testbench tops: the VCS `-sc_portmap` file and the Xcelium foreign-module
# shell header. Both need the evaluated width of every pin, so they are derived
# from the block view plus the per-top widths VLTOPS persisted at database
# creation, and written whole under .gen/vl like the build manifest: no user
# region, regenerated by `make gen`, and owned by whichever project's manifest
# lists the top.
import os
from pysrc.intf_gen_utils import sc_boundary_pin_type


def vlBoundaryGen(prj, args):
    manifest = prj.config.getConfig('BUILDMANIFEST')
    outDir = os.path.join(prj.config.getConfig('DIRS')['root'], '.gen', 'vl')
    os.makedirs(outDir, exist_ok=True)

    def write(name, pins, portmapPath, xceliumPath):
        with open(portmapPath, 'w') as f:
            f.write(portmap(name, pins))
        with open(xceliumPath, 'w') as f:
            f.write(xceliumShell(name, pins))

    blockKeys = [prj.vlTops[top['qualifiedTop']]['blockKey'] for top in manifest['vlTops']]
    blockKeys += [prj.vlTops[top['hdlTop']]['blockKey'] for top in manifest['uvmTops']]
    blockData = {key: prj.getBlockData(key, trimRegLeafInstance=True) for key in dict.fromkeys(blockKeys)}
    for top in manifest['vlTops']:
        name = top['qualifiedTop']
        write(name, prj.getVlTopBoundaryPins(blockData[prj.vlTops[name]['blockKey']], name),
              os.path.join(outDir, f'{name}.portmap'), os.path.join(outDir, f'{name}_xcelium.h'))
    # A UVM testbench top takes its widths from the HDL top it instantiates,
    # and its file paths from the database, which also names the shell its
    # registrar includes.
    for top in manifest['uvmTops']:
        data = blockData[prj.vlTops[top['hdlTop']]['blockKey']]
        write(top['qualifiedTop'], prj.getUvmTopBoundaryPins(data, top['hdlTop']),
              top['portmap'], top['xceliumShell'])


def portmap(top, pins):
    lines = [f'# Generated by arch2code (vlBoundary) for HDL top {top}. Do not edit.',
             '# name width HDL-type SystemC-type']
    for pin in pins:
        hdlType, scType = ('bitvector', 'sc_bv') if pin['vector'] else ('bit', 'bool')
        lines.append(f"{pin['pin']} {pin['width']} {hdlType} {scType}")
    return '\n'.join(lines) + '\n'


def xceliumShell(top, pins):
    guard = f'{top.upper()}_XCELIUM_H_'
    out = [f'// Generated by arch2code (vlBoundary) for HDL top {top}. Do not edit.',
           f'#ifndef {guard}', f'#define {guard}', '', '#include "systemc.h"', '',
           f'class {top} : public xmsc_foreign_module {{', 'public:']
    for pin in pins:
        port = 'sc_in' if pin['direction'] == 'input' else 'sc_out'
        out.append(f"    {port}<{sc_boundary_pin_type(pin)}> {pin['pin']};")
    inits = ', '.join(['xmsc_foreign_module(nm)'] + [f"{pin['pin']}(\"{pin['pin']}\")" for pin in pins])
    out += ['',
            f'    explicit {top}(sc_module_name nm) : {inits} {{}}',
            f'    const char* hdl_name() const override {{ return "{top}"; }}',
            '};', '', f'#endif // {guard}']
    return '\n'.join(out) + '\n'
